16	export const useImagePreview = (): UseImagePreviewReturn => {
17	  const [previewState, setPreviewState] = useState<ImagePreviewState>({ open: false, items: [], index: 0 });
18	
19	  const openPreview = useCallback((items: string | string[] | PreviewMediaItem[], index = 0) => {
20	    const normalizedItems = normalizePreviewItems(items);
21	    setPreviewState({ open: true, items: normalizedItems, index });
22	  }, []);
23	
24	  const setPreviewOpen = useCallback((open: boolean) => {
25	    setPreviewState((prev) => ({ ...prev, open }));
