31	function normalizePreviewItems(items: string | string[] | PreviewMediaItem[]): PreviewMediaItem[] {
32	  if (typeof items === "string") {
33	    return [
34	      {
35	        id: items,
36	        kind: "image",
37	        sourceUrl: items,
38	        posterUrl: items,
39	        filename: "Image",
40	      },
41	    ];
42	  }
43	
44	  if (Array.isArray(items) && (items.length === 0 || typeof items[0] === "string")) {
45	    return (items as string[]).map((url) => ({
46	      id: url,
47	      kind: "image",
48	      sourceUrl: url,
49	      posterUrl: url,
