**`web/src/hooks/useLocalStorage.ts`** — useLocalStorage(function), readLocalStorageValue(function), SetLocalStorageValue(type_alias)

```typescript
1	import { useCallback, useEffect, useRef, useState } from "react";
2	
3	type SetLocalStorageValue<T> = T | ((currentValue: T) => T);
4	
5	const readLocalStorageValue = <T>(key: string, defaultValue: T): T => {
6	  if (typeof window === "undefined") {
7	    return defaultValue;
8	  }
9	
10	  try {
11	    const storedValue = window.localStorage.getItem(key);
12	    return storedValue === null ? defaultValue : (JSON.parse(storedValue) as T);
13	  } catch {
14	    return defaultValue;
15	  }
16	};
17	
18	export const useLocalStorage = <T>(key: string, defaultValue: T): [T, (value: SetLocalStorageValue<T>) => void] => {
19	  const defaultValueRef = useRef(defaultValue);
20	  defaultValueRef.current = defaultValue;
21	
22	  const [storedValue, setStoredValue] = useState<T>(() => readLocalStorageValue(key, defaultValue));
23	
24	  useEffect(() => {
25	    setStoredValue(readLocalStorageValue(key, defaultValueRef.current));
26	  }, [key]);
27	
28	  const setValue = useCallback(
29	    (value: SetLocalStorageValue<T>) => {
30	      setStoredValue((currentValue) => {
31	        const nextValue = typeof value === "function" ? (value as (currentValue: T) => T)(currentValue) : value;
32	
33	        if (typeof window !== "undefined") {
34	          try {
35	            window.localStorage.setItem(key, JSON.stringify(nextValue));
36	          } catch {
37	            // Keep React state updated even if persistence is unavailable.
38	          }
39	        }
40	
41	        return nextValue;
42	      });
43	    },
44	    [key],
45	  );
46	
47	  return [storedValue, setValue];
48	};
```

