**`internal/ai/stt/stt.go`** — Request(struct)

```go
1	// Package stt defines the speech-to-text capability for AI providers.
2	// Implementations call dedicated STT endpoints (e.g. OpenAI /audio/transcriptions)
3	// and return deterministic transcription output. For multimodal LLMs that
4	// happen to accept audio input, see internal/ai/audiollm.
5	package stt
6	
7	import (
8		"context"
9		"io"
10	)
11	
12	// Transcriber transcribes audio to text using a provider's dedicated STT endpoint.
13	type Transcriber interface {
14		Transcribe(ctx context.Context, req Request) (*Response, error)
15	}
16	
17	// Request is the input to a transcription call.
18	type Request struct {
19		Audio       io.Reader
20		Size        int64
21		Filename    string
22		ContentType string // IANA media type, e.g. "audio/wav"
23		Model       string // provider-specific model id (e.g. "whisper-1", "gpt-4o-transcribe")
24		Prompt      string // soft spelling/vocabulary hint (Whisper "prompt" parameter)
25		Language    string // ISO 639-1, optional
26	}
27	
28	// Response is the output of a transcription call.
29	type Response struct {
30		Text     string
31		Language string    // empty if provider did not return it
32		Segments []Segment // empty unless provider returned timestamps
33	}
34	
35	// Segment is a timestamped portion of the transcript.
